/// <summary>
/// METCoverNoteDP class.
/// </summary>
[SrsReportParameterAttribute(classStr(METCoverNoteContract))]
public class METCoverNoteDP extends SrsReportDataProviderPreProcessTempDB
{
    MetLoadId                       loadId;
    METCoverNoteContract            contract;
    METCoverNoteTotesTmp            totesTmp;
    METCoverNoteHeaderTmp           headerTmp;
    METCoverNoteSalesOrdersTmp      salesOrdersTmp;
    METCoverNoteProductTypesTmp     productTypesTmp;
    METCoverNoteTrasnferOrderTmp    transferOrderTmp;

    METBundleGuid         bundleHeaderReportGuid;
    METBundleGuid         headerReportGuid;

}

Method.Source:
/// <summary>
/// Set the bundling guid values to the tmp tables
/// </summary>
/// <param name = "_bundleHeaderReportGuid">Bundle header report guid</param>
/// <param name = "_headerReportGuid">Header report guid</param>
public void setBundlingGuid(METBundleGuid     _bundleHeaderReportGuid, METBundleGuid    _headerReportGuid)
{
    bundleHeaderReportGuid = _bundleHeaderReportGuid;
    headerReportGuid = _headerReportGuid;
}

    /// <summary>
    /// ProcessReport
    /// </summary>
    public void processReport()
    {
        CompanyInfo                         companyInfo = CompanyInfo::find();
        METIndustryKeyLogo                  reportLogo;
        Image                               img;
        MetContainerTable                   containerTable;
        METContainerTypeTable               containerType;
        METIndustryKeyTable                 industryKeyTable;
        CustTable                           custTable;
        METCustTable                        metCustTable;
        SalesTable                          salesTable;
        InventTransferTable                 transferTable;
        InventLocation                      inventLocation;
        InventLocationId                    inventLocationId;
        CustParameters                      custParameters;
        Qty                                 securityCartons;
        TMSCarrier                          tmsCarrier;
        METSalesOrderShipmentLoadLines      shipmentLoadLines;
        TMSSalesTable                       tmsSalesTable;
        METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;
        METSalesOrderShipmentLoadLines      metSalesOrderShipmentLoadLines;
        
        contract = this.parmDataContract();

        const str containerTypeCodeCHP = 'CHP';
        const str containerTypeCodeLOS = 'LOS';
        const str containerTypeCodeLFT = 'LFT';
        const str containerTypeCodeBLT = 'BLT';
        const str containerTypeCodePLN = 'PLN';

        select firstonly ToWarehouse, Route, RouteStopNum, ShipmentId from metSalesOrderShipmentLoadHeader
            where metSalesOrderShipmentLoadHeader.ShipmentId == contract.parmShipmentId();

        if (metSalesOrderShipmentLoadHeader.RecId)
        {
            select firstonly METRevision, METRevisionDate, METDocumentNumber from  custParameters;

            select firstonly custTable
                join RecId from metCustTable
                where custTable.AccountNum == metSalesOrderShipmentLoadHeader.CustAccount
                   && custTable.AccountNum == metCustTable.AccountNum
                join Logo, CompanyName, CoRegNum from industryKeyTable
                where industryKeyTable.IndustryKey == metCustTable.IndustryKey;
           
            headerTmp.IndustryKey           = metCustTable.IndustryKey; //Task 226480: CB272 - Branding details update - Reports
            headerTmp.ShipmentId            = metSalesOrderShipmentLoadHeader.ShipmentId;
            headerTmp.CompanyName           = industryKeyTable.CompanyName;
            headerTmp.CompanyABN            = industryKeyTable.CoRegNum;
            headerTmp.PODNumber             = "test num seq";// METCoverNoteDP::getNumberSeq();
            headerTmp.Revision              = custParameters.METRevision;
            headerTmp.RevisionDate          = custParameters.METRevisionDate;
            headerTmp.DocumentNumber        = custParameters.METDocumentNumber;
            headerTmp.CustomerAccountNumber = custTable.AccountNum;
            headerTmp.CustomerName          = custTable.name();
            headerTmp.CustomerAddress       = custTable.mcrDefaultDeliveryPostalAddress().Address;
            headerTmp.CustomerPhone         = custTable.phone();
            headerTmp.ReportDateTime        = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
            headerTmp.ReportUser            = XUserInfo::find(false, curUserId()).name;

            //Get the carrier code from the <c>TMSSalesTable</c>
            select firstonly CarrierCode from tmsSalesTable
                exists join shipmentLoadLines
                order by OrderNum asc
                    where tmsSalesTable.SalesId == shipmentLoadLines.OrderNum
                    && shipmentLoadLines.ShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId;

            if (tmsSalesTable.CarrierCode)
            {
                headerTmp.Carrier = tmsSalesTable.CarrierCode;
            }

            while select ContainerTypeCode, ContainerQty from containerTable
                where containerTable.ShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId
            {
                if (containerTable.ContainerTypeCode == containerTypeCodeCHP)
                {
                    headerTmp.ChepPalletCount += containerTable.ContainerQty;
                }
                else if (containerTable.ContainerTypeCode == containerTypeCodeLOS)
                {
                    headerTmp.LoscamPalletCount += containerTable.ContainerQty;
                }
                else if (containerTable.ContainerTypeCode == containerTypeCodeLFT)
                {
                    headerTmp.PalletLiftCount += containerTable.ContainerQty;
                }
                else if (containerTable.ContainerTypeCode == containerTypeCodeBLT)
                {
                    headerTmp.CoolerBlanketCount += containerTable.ContainerQty;
                }
                else if (containerTable.ContainerTypeCode == containerTypeCodePLN)
                {
                    headerTmp.PlainPalletCount += containerTable.ContainerQty;
                }
            }

            while select  ItemId, Quantity, RecId, LineNum, OrderNum, InventTransId from metSalesOrderShipmentLoadLines
                exists join metSalesOrderShipmentLoadHeader
                where  metSalesOrderShipmentLoadLines.shipmentid == metSalesOrderShipmentLoadHeader.ShipmentId
                    && metSalesOrderShipmentLoadHeader.ShipmentId == contract.parmShipmentId()
            {
                headerTmp.OrderNumber = metSalesOrderShipmentLoadLines.OrderNum;

                if (SalesTable::exist(metSalesOrderShipmentLoadLines.OrderNum))
                {
                    if (!inventLocationId)
                    {
                        select firstonly salesTable
                        where salesTable.SalesId == metSalesOrderShipmentLoadLines.OrderNum;

                        inventLocationId = salesTable.InventLocationId;
                    }
                    salesOrdersTmp.clear();

                    salesOrdersTmp.SalesId                      = metSalesOrderShipmentLoadLines.OrderNum;
                    salesOrdersTmp.BundleReportHeaderGuidStr    = bundleHeaderReportGuid;
                    salesOrdersTmp.CoverNotesHeaderGuidStr      = headerReportGuid;
                    salesOrdersTmp.insert();

                    this.addProductTypesSalesOrder(metSalesOrderShipmentLoadLines.OrderNum, metSalesOrderShipmentLoadHeader.ShipmentId);
                }
                else if (InventTransferTable::exist(metSalesOrderShipmentLoadLines.OrderNum))
                {
                    if (!inventLocationId)
                    {
                        select firstonly transferTable
                            where transferTable.TransferId == metSalesOrderShipmentLoadLines.OrderNum;

                        inventLocationId = transferTable.InventLocationIdFrom;
                    }
                    transferOrderTmp.clear();

                    transferOrderTmp.TransferId                 = metSalesOrderShipmentLoadLines.OrderNum;
                    transferOrderTmp.BundleReportHeaderGuidStr    = bundleHeaderReportGuid;
                    transferOrderTmp.CoverNotesHeaderGuidStr      = headerReportGuid;
                    transferOrderTmp.insert();
                }

                // BUG228510_CB731_METCoverNoteTotesTmp -- Begin
                this.addTotes(metSalesOrderShipmentLoadLines.OrderNum, metSalesOrderShipmentLoadLines.ItemId);
                // BUG228510_CB731_METCoverNoteTotesTmp -- End
            }

            if (inventLocationId)
            {
                select firstonly inventLocation
                    where inventLocation.InventLocationId == inventLocationId;

                headerTmp.WarehouseName     = inventLocation.Name;
                headerTmp.WarehouseAddress  = inventLocation.address();

                while select containerType
                    where containerType.InventLocationId == inventLocationId
                {
                    if (containerType.ContainerTypeCode == containerTypeCodeCHP)
                    {
                        headerTmp.PalletContainerWeight += headerTmp.PalletContainerWeight + (headerTmp.ChepPalletCount * containerType.Weight);
                    }
                    else if (containerType.ContainerTypeCode == containerTypeCodeLOS)
                    {
                        headerTmp.PalletContainerWeight += headerTmp.PalletContainerWeight + (headerTmp.LoscamPalletCount * containerType.Weight);
                    }
                    else if (containerType.ContainerTypeCode == containerTypeCodeLFT)
                    {
                        headerTmp.PalletContainerWeight += headerTmp.PalletContainerWeight + (headerTmp.PalletLiftCount * containerType.Weight);
                    }
                    else if (containerType.ContainerTypeCode == containerTypeCodeBLT)
                    {
                        headerTmp.PalletContainerWeight += headerTmp.PalletContainerWeight + (headerTmp.CoolerBlanketCount * containerType.Weight);
                    }
                    else if (containerType.ContainerTypeCode == containerTypeCodePLN)
                    {
                        headerTmp.PalletContainerWeight += headerTmp.PalletContainerWeight + (headerTmp.PlainPalletCount * containerType.Weight);
                    }
                }
            }

            headerTmp.SecurityCartons               = 1;
            headerTmp.CarrierName                   = tmsCarrier.Name;
            headerTmp.RunNumber                     = metSalesOrderShipmentLoadHeader.Route;
            headerTmp.BundleReportHeaderGuidStr     = bundleHeaderReportGuid;
            headerTmp.CoverNotesHeaderGuidStr       = headerReportGuid;

            headerTmp.insert();

        }
    }

    /// <summary>
    /// Add product types for the sales order.
    /// </summary>
    /// <param name = "_salesId">Sales order number</param>
    /// <param name = "_shipmentId">Shipment number</param>
    public void addProductTypesSalesOrder(SalesId _salesId, MetShipmentId _shipmentId)
    {
        SalesLine                   salesLine;
        METSalesLine                metSalesLine;
        InventDim                   inventDim;
        MetContainerTable           containerTable;
        METInventItemOrderSetup     metInventItemOrderSetup;

        while select salesLine where salesLine.SalesId == _salesId
            join metSalesLine
            where metSalesLine.SalesLine == salesLine.RecId
                join RecId from inventDim
                where inventDim.inventDimId == salesLine.InventDimId
                    join ItemType from metInventItemOrderSetup
                    where metInventItemOrderSetup.ItemId == salesLine.ItemId
                        && metInventItemOrderSetup.SiteId == inventDim.InventSiteId
        {
            productTypesTmp.clear();

            productTypesTmp.ProductType                 = metInventItemOrderSetup.ItemType;
            productTypesTmp.GrossWeight                 = salesLine.displayMETGrossWeight();
            productTypesTmp.ProductTotalWeight          = salesLine.displayMETGrossWeight();
            productTypesTmp.METCase                     = salesLine.displayMETcases();
            productTypesTmp.BrokenCase                  = salesLine.displayMETBrokenCase();

            while select ContainerTypeCode, ContainerQty from containerTable
                where containerTable.ShipmentId == _shipmentId
            {
                productTypesTmp.PalletContainerTotalWeight += salesLine.displayMETGrossWeight() * containerTable.ContainerQty;    
            }

            productTypesTmp.TotalWeight                 = productTypesTmp.ProductTotalWeight + productTypesTmp.PalletContainerTotalWeight;
            productTypesTmp.BundleReportHeaderGuidStr   = bundleHeaderReportGuid; //contract.parmBundleHeaderReportGuid();
            productTypesTmp.CoverNotesHeaderGuidStr     = headerReportGuid; //contract.parmHeaderTableGuid();
            productTypesTmp.insert();
        }
    }

    /// <summary>
    /// Add product types for the transfer order.
    /// </summary>
    /// <param name = "_transferId">Transfer order number</param>
    /// <param name = "_shipmentId">Shipment number</param>
    public void addProductTypesTransferOrder(InventTransferId _transferId, MetShipmentId _shipmentId)
    {
        InventTransferLine          transferLine;
        METInventTransferLine       metTransferLine;
        InventDim                   inventDim;
        MetContainerTable           containerTable;
        METInventItemOrderSetup     metInventItemOrderSetup;

        while select transferLine where transferLine.TransferId == _transferId
            join metTransferLine
            where metTransferLine.InventTransferLine == transferLine.RecId
                join RecId from inventDim
                where inventDim.inventDimId == transferLine.InventDimId
                    join ItemType from metInventItemOrderSetup
                    where metInventItemOrderSetup.ItemId == transferLine.ItemId
                        && metInventItemOrderSetup.SiteId == inventDim.InventSiteId
        {
            productTypesTmp.clear();

            productTypesTmp.ProductType                 = metInventItemOrderSetup.ItemType;
            productTypesTmp.GrossWeight                 = transferLine.displayMETGrossWeight();
            productTypesTmp.ProductTotalWeight          = transferLine.displayMETGrossWeight();
            productTypesTmp.METCase                     = transferLine.displayMETcases();
            productTypesTmp.BrokenCase                  = transferLine.displayMETBrokenCase();

            while select ContainerTypeCode, ContainerQty from containerTable
                where containerTable.ShipmentId == _shipmentId
            {
                productTypesTmp.PalletContainerTotalWeight += productTypesTmp.ProductTotalWeight * containerTable.ContainerQty;
            }

            productTypesTmp.TotalWeight                 = productTypesTmp.ProductTotalWeight + productTypesTmp.PalletContainerTotalWeight;
            productTypesTmp.BundleReportHeaderGuidStr   = bundleHeaderReportGuid; //contract.parmBundleHeaderReportGuid();
            productTypesTmp.CoverNotesHeaderGuidStr     = headerReportGuid; //contract.parmHeaderTableGuid();
            productTypesTmp.insert();
        }
    }

/// <summary>
/// productTypesTmp
/// </summary>
/// <returns>METCoverNoteProductTypesTmp</returns>
[SrsReportDataSet(tableStr(METCoverNoteProductTypesTmp))]
public METCoverNoteProductTypesTmp getLinesTmp()
{
    select productTypesTmp;
    return productTypesTmp;
}

